import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`medspa-consult-followup`,heroTitle:`Automate your consult follow-ups in minutes`,heroSubtitle:`Perplexity Computer reviews your consultation notes, drafts personalized follow-up messages, and builds treatment-specific care plans — automatically.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Upload consult notes`,inputFileAccept:`.pdf,.doc,.docx`,inputFilePrefill:`Review the uploaded consultation notes and generate a complete medspa follow-up package. 1) Extract patient details, treatment discussed, skin concerns, contraindications, and provider recommendations from the notes. 2) Draft a personalized follow-up email to the patient — warm, professional tone — summarizing the consultation, recommended treatments, expected results, and next steps. 3) Generate a pre-treatment preparation guide tailored to the specific procedure discussed (e.g., Botox, fillers, laser, chemical peel, microneedling). 4) Create a post-treatment care instruction sheet for the recommended procedure. 5) Draft a booking reminder message with a clear CTA to schedule the appointment. 6) Build a follow-up sequence timeline — Day 1, Day 3, Day 7, Day 14 — with suggested touchpoints and messaging for each. 7) Flag any noted allergies, medications, or contraindications that require provider review before treatment.`,heroOverlaySteps:[`Reviewing consultation notes for treatments, concerns, and recommendations`,`Drafting personalized follow-up emails and care instructions`,`Building a treatment-specific follow-up sequence timeline`,`Follow-up package with emails, care guides, and booking reminders — ready to send`],generatingSteps:[`Analyzing the uploaded file for patient details, treatments, and provider notes`,`Designing an agent to draft personalized follow-up messages and care instructions`,`Configuring treatment-specific prep guides, post-care sheets, and follow-up sequences`,`Setting up booking reminders and contraindication flags for provider review`],featureSectionTitle:`From consult notes to follow-up package`,featureCardTitles:[`Connects to your medspa stack`,`Outputs you can send today`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Gmail, Google Docs, Google Sheets, Notion, Slack — Computer sends follow-ups and stores care plans in the tools your team already uses.`,`Personalized follow-up emails. Pre-treatment prep guides. Post-care instruction sheets. Booking reminders. Multi-day follow-up sequences. Contraindication flags.`],capabilitySectionTitle:`Your patient coordinator, on autopilot`,capabilitySectionSubtitle:`Upload your consult notes, step away, come back to a complete follow-up package.`,capabilityCards:[{title:`Note Extraction`,description:`Computer can parse consultation notes — treatments discussed, skin concerns, contraindications, and provider recommendations — into structured patient profiles.`},{title:`Follow-Up Drafting`,description:`Computer can write personalized follow-up emails that summarize the consultation, outline recommended treatments, and include a clear booking CTA.`},{title:`Care Instructions`,description:`Computer can generate treatment-specific pre-care and post-care guides — tailored to Botox, fillers, laser, chemical peels, microneedling, and more.`},{title:`Connect Your Tools`,description:`Computer can send follow-ups through Gmail, log patient details in Google Sheets, and store care plans in Google Drive or Notion — all in one workflow.`},{title:`Remember & Learn`,description:`Computer can remember your clinic's tone, treatment protocols, and preferred messaging — so every follow-up sounds like your brand.`},{title:`Monitor & Alert`,description:`Computer can flag overdue follow-ups, track which patients haven't booked, and alert your team when it's time for the next touchpoint.`}]});export{t as default};
